from pptx import Presentation
from pptx.util import Inches, Pt
from pptx.dml.color import RGBColor
from pptx.enum.shapes import MSO_SHAPE, MSO_CONNECTOR
from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
from pptx.oxml.xmlchemy import OxmlElement
from pathlib import Path
import json

OUT=Path('/project/outputs')
R=Presentation(); R.slide_width=Inches(13.333); R.slide_height=Inches(7.5)
NAVY='0F3666'; WHITE='FFFFFF'; YELLOW='F4C542'; SOFT='EDF2F8'; MUTED='4E6682'
records=[]
def rgb(c):return RGBColor.from_string(c)
def rect(s,x,y,w,h,fill=SOFT,line=None,kind=MSO_SHAPE.ROUNDED_RECTANGLE):
 q=s.shapes.add_shape(kind, Inches(x), Inches(y), Inches(w), Inches(h)); q.fill.solid(); q.fill.fore_color.rgb=rgb(fill); q.line.color.rgb=rgb(line or fill)
 q._element.spPr.append(OxmlElement('a:effectLst'))
 if kind==MSO_SHAPE.ROUNDED_RECTANGLE:q.adjustments[0]=0.12
 return q

def text(s,x,y,w,h,t,size=20,color=NAVY,bold=False,center=False,title=False):
 q=s.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h)); tf=q.text_frame; tf.word_wrap=True
 tf.margin_left=Inches(.10);tf.margin_right=Inches(.10);tf.margin_top=Inches(.04);tf.margin_bottom=Inches(.03)
 for i,line in enumerate(t.split('\n')):
  p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=line;p.alignment=PP_ALIGN.CENTER if center else PP_ALIGN.RIGHT;p.space_after=Pt(8)
  pp=p._p.get_or_add_pPr();pp.set('rtl','1')
  for run in p.runs:
   run.font.name='Lalezar' if title else 'Vazirmatn';run.font.size=Pt(size);run.font.bold=bold;run.font.color.rgb=rgb(color)
   rp=run._r.get_or_add_rPr();rp.set('lang','fa-IR');e=OxmlElement('a:cs');e.set('typeface','Lalezar' if title else 'Vazirmatn');rp.append(e)
 return q

def base(title,section='راهبرد محصول',dark=False,tag=''):
 s=R.slides.add_slide(R.slide_layouts[6]);s.background.fill.solid();s.background.fill.fore_color.rgb=rgb(NAVY if dark else WHITE)
 col=WHITE if dark else NAVY
 rect(s,12.35,.5,.34,.34,YELLOW,kind=MSO_SHAPE.OVAL)
 text(s,.65,.45,11.45,.88,title,32,col,title=True)
 text(s,.7,7.02,10.9,.3,'SpeakFlow  /  '+section+'   •   نسخهٔ راهبردی اولیه | ۱۰ نوامبر ۲۰۲۶',10,WHITE if dark else MUTED)
 text(s,11.8,6.95,.8,.4,str(len(R.slides)).zfill(2),15,YELLOW if dark else NAVY,center=True)
 if tag:text(s,.7,1.32,11.8,.45,tag,12,YELLOW if dark else MUTED)
 return s

def notes(s,t):s.notes_slide.notes_text_frame.text=t

def cards(title,items,section='راهبرد محصول',tag='',note=''):
 s=base(title,section,tag=tag);n=len(items);cols=2 if n in (2,4) else 3; rows=(n+cols-1)//cols
 w=(11.9-.22*(cols-1))/cols;h=(4.65-.22*(rows-1))/rows
 for i,(head,body) in enumerate(items):
  x=12.6-w-(i%cols)*(w+.22);y=1.94+(i//cols)*(h+.22)
  rect(s,x,y,w,h);rect(s,x+w-.51,y+.19,.24,.24,YELLOW,kind=MSO_SHAPE.OVAL)
  text(s,x+.15,y+.44,w-.3,.64,head,23,title=True)
  text(s,x+.15,y+1.13,w-.3,h-1.22,body,17 if rows==1 else 15)
 notes(s,note or '\n\n'.join(a+'\n'+b for a,b in items));records.append({'title':title,'items':items,'notes':note})
 return s

def statement(title,big,small,section='فلسفهٔ محصول'):
 s=base(title,section,True);text(s,1.1,2.2,11.1,2.0,big,37,WHITE,title=True,center=True);text(s,1.6,4.65,10.1,1.3,small,21,WHITE,center=True)
 notes(s,big+'\n'+small);records.append({'title':title,'text':big,'detail':small});return s

def table(title,headers,rows,section='مدل کسب‌وکار',tag='',note=''):
 s=base(title,section,tag=tag);width=11.9; x=.72;y=1.95;cw=width/len(headers);rh=min(.76,4.7/(len(rows)+1))
 for r,row in enumerate([headers]+rows):
  for c,val in enumerate(row):
   xx=x+width-(c+1)*cw;rect(s,xx,y+r*rh,cw-.035,rh-.035,NAVY if r==0 else (SOFT if r%2 else 'F8FAFC'),kind=MSO_SHAPE.RECTANGLE)
   text(s,xx+.045,y+r*rh+.04,cw-.13,rh-.08,str(val),14 if len(headers)>3 else 16,WHITE if r==0 else NAVY,bold=r==0)
 notes(s,note or '\n'.join(' | '.join(row) for row in [headers]+rows));records.append({'title':title,'headers':headers,'rows':rows,'notes':note});return s

def arrow(s,x1,y1,x2,y2,label=''):
 c=s.shapes.add_connector(MSO_CONNECTOR.STRAIGHT, Inches(x1), Inches(y1), Inches(x2), Inches(y2));c.line.color.rgb=rgb(NAVY);c.line.width=Pt(2)
 ln=c._element.spPr.get_or_add_ln();end=OxmlElement('a:tailEnd');end.set('type','triangle');ln.append(end)
 if label:text(s,min(x1,x2)-.05,min(y1,y2)-.35,max(.7,abs(x2-x1)),.35,label,11,center=True)

def flow(code,title,steps,branch,detail):
 s=base(code+' | '+title,'پیوست یوزرفلوها',tag='بیضی: شروع/پایان   •   مستطیل: اقدام/صفحه   •   لوزی: تصمیم   •   فلش: جهت حرکت')
 xs=[10,6.3,2.6,2.6,6.3,10];ys=[2.05,2.05,2.05,4.4,4.4,4.4];w=2.6;h=1.12
 for i,t in enumerate(steps):
  k=MSO_SHAPE.DIAMOND if i==2 else MSO_SHAPE.ROUNDED_RECTANGLE
  if i in (0,5):k=MSO_SHAPE.OVAL
  rect(s,xs[i],ys[i],w,h,YELLOW if i==2 else SOFT,NAVY,k)
  text(s,xs[i]+.10,ys[i]+.18,w-.20,.78,t,15,center=True)
 arrow(s,10,2.61,8.9,2.61);arrow(s,6.3,2.61,5.2,2.61)
 arrow(s,3.9,3.17,3.9,4.4,'بله');arrow(s,5.2,4.96,6.3,4.96);arrow(s,8.9,4.96,10,4.96)
 rect(s,.40,3.28,1.90,1.4,'FFF8D9',NAVY)
 text(s,.47,3.43,1.76,1.12,branch,13,center=True)
 arrow(s,2.6,2.61,1.35,3.28,'خیر')
 text(s,1,5.99,11.3,.68,detail,15)
 notes(s,'شناسه '+code+'\nمسیر اصلی: '+' ← '.join(steps)+'\nشاخهٔ خیر: '+branch+'\n'+detail)
 records.append({'flow':code,'title':title,'steps':steps,'no_branch':branch,'detail':detail})

