sources=[
('S1','لرنووا | وب‌سایت؛ واکشی مستقیم','https://learnova.app'),
('S2','لرنووا | کانال؛ نتیجهٔ جست‌وجو، واکشی ناموفق','https://t.me/s/learnova_channel?before=232'),
('S3','لرنووا | بازنشر ثانویه، نه حساب رسمی','https://imginn.com/learnova.app/'),
('S4','Talkpal | قیمت و ویژگی‌ها؛ واکشی مستقیم','https://talkpal.ai/pricing/'),
('S5','Praktika | معرفی و قیمت تقریبی؛ واکشی مستقیم','https://praktika.ai/'),
('S6','Praktika | راهنما؛ نمایه‌شده، واکشی ناموفق','https://intercom.help/praktika-ai/en/articles/12008580-is-there-a-free-version-of-the-app-available-or-do-i-need-a-subscription')]
for j in range(0,len(sources),3):
 s=base('منابع عمومی | '+str(j//3+1),'منابع',tag='تاریخ بررسی: ۱۰ نوامبر ۲۰۲۶؛ مبلغ پویا، ادعای تبلیغاتی و دادهٔ نامشخص تفکیک شده‌اند.')
 for k,(sid,desc,url) in enumerate(sources[j:j+3]):
  y=2+k*1.43;rect(s,.8,y,11.7,1.22)
  text(s,1,y+.09,11.25,.45,sid+' | '+desc,17)
  q=text(s,1,y+.64,11.25,.45,url,12)
  for p in q.text_frame.paragraphs:
   p.alignment=PP_ALIGN.LEFT
   for run in p.runs:run.hyperlink.address=url
 notes(s,'\n'.join(a+' '+b+'\n'+c for a,b,c in sources[j:j+3]))
